using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Diagnostics;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using SplifyWin;
class UiPerformanceCheck {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool value,string message){if(!value)throw new Exception(message);Console.WriteLine("PASS "+message);}
 static void HeaderDoubleClick(MainForm form){var dashboard=(Control)typeof(MainForm).GetField("blueDashboard",Flags).GetValue(form);var previous=form.WindowState;dashboard.GetType().GetMethod("OnMouseDoubleClick",Flags).Invoke(dashboard,new object[]{new MouseEventArgs(MouseButtons.Left,2,500,30,0)});Application.DoEvents();Assert(form.WindowState!=previous,"title-bar double click maximizes/restores");dashboard.GetType().GetMethod("OnMouseDoubleClick",Flags).Invoke(dashboard,new object[]{new MouseEventArgs(MouseButtons.Left,2,500,30,0)});Application.DoEvents();Assert(form.WindowState==previous,"second title-bar double click restores previous state");}
 static void GeneratorResize(MainForm form,string root){typeof(MainForm).GetMethod("ShowPage",Flags).Invoke(form,new object[]{"strategy-workshop"});Application.DoEvents();typeof(MainForm).GetMethod("ToggleWindowMaximize",Flags).Invoke(form,null);Application.DoEvents();var overlay=(Panel)typeof(MainForm).GetField("popupOverlay",Flags).GetValue(form);using(var image=new Bitmap(overlay.Width,overlay.Height)){overlay.DrawToBitmap(image,new Rectangle(Point.Empty,overlay.Size));image.Save(Path.Combine(root,"generator-maximized.png"));typeof(MainForm).GetMethod("ShowPage",Flags).Invoke(form,new object[]{"strategy-workshop"});Application.DoEvents();overlay=(Panel)typeof(MainForm).GetField("popupOverlay",Flags).GetValue(form);using(var fresh=new Bitmap(overlay.Width,overlay.Height)){overlay.DrawToBitmap(fresh,new Rectangle(Point.Empty,overlay.Size));int differences=0,samples=0;for(int y=16;y<image.Height;y+=8)for(int x=16;x<image.Width;x+=8){samples++;if(image.GetPixel(x,y)!=fresh.GetPixel(x,y))differences++;}Console.WriteLine("RESIZE bitmap differences: "+differences+" / "+samples);Assert(differences==0,"resized generator matches fresh layout with no stale cached background");}}typeof(MainForm).GetMethod("ToggleWindowMaximize",Flags).Invoke(form,null);Application.DoEvents();typeof(MainForm).GetMethod("ShowPage",Flags).Invoke(form,new object[]{"zapret"});Application.DoEvents();Assert(form.Controls.Find("zapretStrategyGenerator",true).Single().Text=="Генератор стратегий"&&form.Controls.Find("zapretStrategyEditor",true).Single().Text=="Редактор стратегий","strategy tools available inside Zapret");}
 [STAThread]static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("MCRF_DATA_DIR",root);Environment.SetEnvironmentVariable("SPLIFY_WIN_DATA_DIR",root);Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_SETUP","1");Environment.SetEnvironmentVariable("MCRF_TEST_NO_STARTUP_UPDATES","1");using(var form=new MainForm(false,false)){form.Size=new Size(1366,865);form.Show();Application.DoEvents();var state=(ClientState)typeof(MainForm).GetField("state",Flags).GetValue(form);state.AdvancedMode=true;UiTheme.Simple=true;SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());foreach(int n in new[]{7,20,80}){state.Lists=Enumerable.Range(0,n).Select(i=>new RouteList{Name="Test "+i,Text="example"+i+".com",Target="direct",Enabled=true}).ToList();var watch=Stopwatch.StartNew();typeof(MainForm).GetMethod("ShowPage",Flags).Invoke(form,new object[]{"routes"});DateTime until=DateTime.Now.AddSeconds(20);while(form.Controls.Find("routeTable",true).Length==0&&DateTime.Now<until){Application.DoEvents();Thread.Sleep(5);}Application.DoEvents();watch.Stop();Console.WriteLine("ROUTES "+n+": "+watch.ElapsedMilliseconds+" ms");var grid=form.Controls.Find("routeTable",true).OfType<DataGridView>().Single();Assert(grid.Rows.Count==n,"all rows installed "+n);Assert(grid.Controls.OfType<GlassPicker>().Count()==n*4,"all inline controls installed "+n);grid.FirstDisplayedScrollingRowIndex=Math.Max(0,n-4);Application.DoEvents();Assert(grid.Controls.OfType<GlassPicker>().Where(c=>c.Visible).All(c=>c.Bottom>grid.ColumnHeadersHeight&&c.Top<grid.Height),"scrolled editors clipped correctly "+n);watch.Restart();for(int j=0;j<4;j++){typeof(MainForm).GetMethod("ToggleWindowMaximize",Flags).Invoke(form,null);Application.DoEvents();}watch.Stop();Console.WriteLine("MAXIMIZE/RESTORE x4 "+n+": "+watch.ElapsedMilliseconds+" ms");Assert(!form.Controls.Cast<Control>().Any(c=>c.GetType().Name=="GlassMotionLayer"),"no stale animation layer after resizing "+n);typeof(MainForm).GetMethod("ShowPage",Flags).Invoke(form,new object[]{"home"});Application.DoEvents();}GeneratorResize(form,root);HeaderDoubleClick(form);form.Close();}return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
